import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, test } from "node:test";
import { GAME_NAMES, readGameNames, writeGameNames } from "./game-names.ts";

const PIN = { gameVersion: "1.12.1.3", sha: "a6995c571a092e762ea036589bb6f3a8fa4f5dbd" };
const HEAD = [
  "// GENERATED by scripts/drift.ts — do not edit.",
  "// Source: pagefaultgames/pokerogue at v1.12.1.3 (a6995c571a092e762ea036589bb6f3a8fa4f5dbd).",
];

let root: string;
const file = () => path.join(root, GAME_NAMES);
const put = (text: string) => writeFileSync(file(), text);
const refusal = () => {
  try {
    readGameNames(root, PIN);
  } catch (e) {
    return (e as Error).message;
  }
  return null;
};

beforeEach(() => {
  root = mkdtempSync(path.join(tmpdir(), "game-names-"));
  mkdirSync(path.dirname(file()), { recursive: true });
});
afterEach(() => rmSync(root, { recursive: true, force: true }));

test("names are written sorted by code unit, once each, under the GENERATED line and the pin, and read back as written", () => {
  assert.deepEqual(writeGameNames(root, PIN, ["b", "#p", "B", "a", "a", "[Symbol.iterator]"]), {
    added: ["#p", "B", "[Symbol.iterator]", "a", "b"],
    removed: [],
  });
  assert.equal(readFileSync(file(), "utf8"), [...HEAD, "#p", "B", "[Symbol.iterator]", "a", "b", ""].join("\n"));
  const read = readGameNames(root, PIN);
  assert.equal(read.version, "1.12.1.3");
  assert.deepEqual([...read.names], [["#p", []], ["B", []], ["[Symbol.iterator]", []], ["a", []], ["b", []]]);
});

test("a second write reports what it added and removed", () => {
  writeGameNames(root, PIN, ["a", "b"]);
  assert.deepEqual(writeGameNames(root, PIN, ["b", "c"]), { added: ["c"], removed: ["a"] });
});

test("a missing file is refused, naming --write-names", () => {
  assert.equal(refusal(), `${GAME_NAMES} is missing: run npm run drift:check -- --write-names`);
});

test("names at another version or sha than the pin are refused, naming both", () => {
  writeGameNames(root, { gameVersion: "1.12.1.2", sha: "3f1c2aa".padEnd(40, "0") }, ["a"]);
  assert.equal(
    refusal(),
    `${GAME_NAMES} is at v1.12.1.2 (3f1c2aa), the pin is v1.12.1.3 (a6995c5): run npm run drift:check -- --write-names`,
  );
});

test("a file not as the writer gives it is refused at its first differing line", () => {
  const at = (line: number) => `${GAME_NAMES} is not as scripts/drift.ts writes it (line ${line}): run npm run drift:check -- --write-names`;
  put(["// a hand-written header", HEAD[1], "a", ""].join("\n"));
  assert.equal(refusal(), at(1));
  put([HEAD[0], "// Source: somewhere", "a", ""].join("\n"));
  assert.equal(refusal(), at(2));
  put([...HEAD, "b", "a", ""].join("\n"));
  assert.equal(refusal(), at(3));
  put([...HEAD, "a", "a", "b", ""].join("\n"));
  assert.equal(refusal(), at(4));
  put([...HEAD, "a", "", "b", ""].join("\n"));
  assert.equal(refusal(), at(4));
  put([...HEAD, "a", "b"].join("\n"));
  assert.equal(refusal(), at(4));
  put([...HEAD, "a", "b", ""].join("\r\n"));
  assert.equal(refusal(), at(1));
});
